def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= 85 and opp.get('budget', 0) >= 300:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgent = hp <= 2 or no_water >= 1
    semi_urgent = hp <= 4

    units = int(supply // WATER_REQ)

    if urgent:
        bid = max(92.0, max_prev + 2.5)
        if desperate_count >= 2:
            bid += 4.0
        return float(min(budget, bid))

    if units >= 1:
        if max_prev >= 100:
            bid = 24.0 if hp >= 6 else 58.0
        elif max_prev >= 90:
            bid = 28.0 if hp >= 6 else 62.0
        elif max_prev >= 75:
            bid = max(46.0, avg_prev * 0.72)
        else:
            bid = max(34.0, max_prev + 1.5)
    else:
        bid = 20.0

    if semi_urgent:
        bid += 12.0
    if desperate_count >= 2:
        bid += 6.0
    if rich_aggressive >= 2 and hp >= 6:
        bid -= 8.0

    if day >= 8 and hp >= 6:
        bid -= 6.0
    if day >= 8 and semi_urgent:
        bid += 6.0

    bid = max(0.0, bid)
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(avg_opp_bid + 5.0, 60.0))

    target_bid = min(avg_opp_bid + 2.0, 55.0)
    return min(my_status['budget'], target_bid)
